document.addEventListener('DOMContentLoaded',()=>{const select=document.querySelector('#stay');if(!select)return;const groups={'1º distrito':['Balneário','Bonfim','Centro','Cidade da Bíblia','Colégio Naval','Ilha da Gipóia','Marinas','Morro da Cruz','Morro da Glória','Morro do Bulé','Morro do Moreno','Paraíso','Parque das Palmeiras','Praia da Chácara','Praia do Anil','Praia do Jardim','Praia Grande','São Bento','Tanguá','Vila Velha'],'2º distrito':['Areal','Ariró','Banqueta','Bracuí','Caieira','Campo Belo','Divinéia','Encruzo da Enseada','Enseada','Gamboa do Belém','Gamboa do Bracuí','Grataú','Ilha da Barra','Ilha do Jorge','Itanema','Japuíba','Nova Angra','Parque Belém','Piraquara','Ponta da Cruz','Ponta do Partido','Ponta do Sapê','Ponta dos Ubás','Pontal','Porto Frade','Praia da Ribeira','Praia do Recife','Retiro','Serra D’água','Sertão de Itanema','Usina Nuclear','Vila Nova','Zungu'],'3º distrito':['Mombaça','Camorim','Camorim Pequeno','Lambicada','Praia do Machado','Jacuacanga','Água Santa','Caputera I','Caputera II','Monsuaba','Portogalo','Pontaleste','Vila da Petrobrás','Vila dos Pescadores','Village Jacuacanga','Terminal da Petrobrás','Biscaia','Caetés','Garatucaia','Maciéis'],'4º distrito':['Parque Mambucaba','Parque Perequê','Praia Brava','Praia das Goiabas','Praia Vermelha','Sertão de Mambucaba','Vila Histórica de Mambucaba','Frade','Reserva Indígena','Santa Rita do Bracuí','Sertão do Bracuí'],'5º distrito':['Abraãozinho','Araçatiba','Aventureiro','Bananal','Dois Rios','Enseada das Estrelas','Enseada das Palmas','Enseada do Sítio Forte','Freguesia de Santana','Guaxuma','Lopes Mendes','Matariz','Parnaioca','Ponta dos Castelhanos','Praia da Longa','Praia Vermelha da Ilha Grande','Provetá','Vila do Abraão']};select.innerHTML='';Object.entries(groups).forEach(([g,items])=>{const o=document.createElement('optgroup');o.label=g;items.forEach(x=>{const op=document.createElement('option');op.textContent=x;op.value=x;o.appendChild(op)});select.appendChild(o)})});
